examples.template:
MonarchFlowLayout(spacing: 0, rowSpacing: 4, alignment: .firstTextBaseline) {
    ForEach(Array(Self.words({{before}}).dropLast().enumerated()), id: \.offset) { _, word in
        Text("\(word) ").monarchTextStyle(.body)
    }
    HStack(alignment: .firstTextBaseline, spacing: 0) {
        Text(Self.words({{before}}).last ?? "").monarchTextStyle(.body)
        MonarchAiCitation(1, source: handbook, quote: {{quote}}, onOpen: { previewed = $0 })
        Text(Self.words({{between}}).first.map { $0 + " " } ?? "").monarchTextStyle(.body)
    }
    ForEach(Array(Self.words({{between}}).dropFirst().dropLast().enumerated()), id: \.offset) { _, word in
        Text("\(word) ").monarchTextStyle(.body)
    }
    HStack(alignment: .firstTextBaseline, spacing: 0) {
        Text(Self.words({{between}}).last ?? "").monarchTextStyle(.body)
        MonarchAiCitation(2, source: policy)
        Text({{after}}).monarchTextStyle(.body)
    }
}
.sheet(item: $previewed) { source in
    MonarchAiSourcePreview(source, quote: {{quote}}, content: {{preview}})
}

